mapper.select:
SELECT A.FINPROD_ID finprodId, A.FINPROD_MARKET_ID finprodMarketId, A.FINPROD_NAME finprodName, A.CCY ccy, A.VDATE vdate, A.MDATE mdate, T.CUSTOMER_NAME manager, A.CALENDAR_ID calendarId, A.CAPI_INCOME_FEATURE capiIncomeFeature,
A.ISSUE_AMT issueAmt, A.FINPROD_TYPE2, B.TYPE_6 category, B.TYPE_7 type,
B.TYPE_9 type9, B.TYPE_10 type10, B.TYPE_11 type11, B.TYPE_12 type12,
FPR.recommender recommender, FPR.recommenderName recommenderName,
(CASE WHEN C.PUR_SPEED = 0 THEN 'T+0' ELSE 'T+1' END) transMode, D.CASH_OUT_NO cmsId, (CASE WHEN A.FINPROD_TYPE2 = #{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR} THEN 'N' ELSE 'Y' END ) parentPlan, D.TRIAL_NO, A.CONTRACT_NO, A.INVEST_ADVISER, T1.CUSTOMER_NAME issuer, T2.CUSTOMER_NAME trusteeId FROM FIN_PRODUCT A inner join FIN_PRODUCT_TYPE B on A.FINPROD_ID = B.FINPROD_ID inner join FIN_PRODUCT_ADD C on A.FINPROD_ID = C.FINPROD_ID inner join PA_FIN_PRODUCT D on A.FINPROD_ID = D.FINPROD_ID
LEFT JOIN ( SELECT FPR.FINPROD_ID, group_concat(FPR.RECOMMENDER order by FPR.RECOMMENDER separator'，') recommender, group_concat(MCP.COUNTER_NAME order by FPR.RECOMMENDER separator'，') recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = A.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO T ON T.CUSTOMER_ID = A.MANAGER LEFT JOIN MST_CUSTOMER_INFO T1 ON T1.CUSTOMER_ID = A.ISSUER LEFT JOIN MST_CUSTOMER_INFO T2 ON T2.CUSTOMER_ID = A.TRUSTEE_ID WHERE 1=1
AND A.FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{finprodMarketId}),'%')
#{type10,jdbcType=VARCHAR}
#{type11,jdbcType=VARCHAR}
#{type12,jdbcType=VARCHAR}
#{type9,jdbcType=VARCHAR}
#{category,jdbcType=VARCHAR}
#{type,jdbcType=VARCHAR}
AND C.PUR_SPEED = (CASE WHEN #{transMode,jdbcType=VARCHAR} ='T+0' THEN 0 WHEN 'T+1' THEN 1 END)
AND A.CCY = #{ccy,jdbcType=VARCHAR}
AND A.FINPROD_TYPE2 in(#{ TYPE_TOUGUAN_F27, jdbcType = VARCHAR})
AND A.FINPROD_TYPE2 in(#{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR})
AND A.FINPROD_TYPE2 in(#{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR},#{ TYPE_TOUGUAN_F27, jdbcType = VARCHAR})
AND A.PROFIT_TYPE = #{PROFIT_TYPE_02, jdbcType = VARCHAR}
AND DATE_FORMAT(A.VDATE,'%Y-%m-%d') > = #{startVDate}
AND DATE_FORMAT(A.VDATE,'%Y-%m-%d') < = #{endVDate}
AND DATE_FORMAT(A.MDATE,'%Y-%m-%d') > = #{startMDate}
AND DATE_FORMAT(A.MDATE,'%Y-%m-%d') < = #{endMDate}
AND A.MANAGER = #{manager,jdbcType=VARCHAR}
AND A.ISSUER = #{issuer,jdbcType=VARCHAR}
AND A.TRUSTEE_ID = #{trusteeId,jdbcType=VARCHAR}
